package com.acme.orders.dto; import com.acme.orders.entity.PurchaseOrder; import java.math.BigDecimal; import java.time.Instant; public record OrderResponse(Long id,String customerEmail,String sku,int quantity,BigDecimal unitPrice,Instant createdAt){public static OrderResponse of(PurchaseOrder o){return new OrderResponse(o.getId(),o.getCustomerEmail(),o.getSku(),o.getQuantity(),o.getUnitPrice(),o.getCreatedAt());}}
